/**
 * 💰 今日入账小组件
 *
 * 在模块设置里填写上班时间、下班时间和每小时工资，
 * 组件按已上班的时长实时计算今日入账，并显示距离下班的倒计时。
 *   WORK_START   上班时间，例：09:00
 *   LUNCH_START  午休开始，例：12:00（不午休就清空）
 *   LUNCH_END    午休结束，例：13:00（不午休就清空）
 *   WORK_END     下班时间，例：18:00
 *   REST_DAYS    本月休息日期号，逗号分隔，例：1,8,15（可留空）
 *   CUSTOM_DAYS  自定义某天工时和金额，格式：日期号:小时:金额，多条用分号隔开，例：5:5:500;12:3.5:350（可留空）
 *   HOURLY_WAGE  每小时工资，例：100
 */

const CHAR_IMG = 'data:image/png;base64,';

export default async function (ctx) {
  return handleWidget(ctx);
}

async function handleWidget(ctx) {
  const safeCtx = ctx || {};
  const env = safeCtx.env || {};
  const family = safeCtx.widgetFamily || 'systemMedium';

  function parseTime(str, fallback) {
    if (str == null) return fallback;
    const m = String(str).replace('：', ':').match(/(\d{1,2})\s*:\s*(\d{1,2})/);
    if (m) {
      const h = parseInt(m[1], 10);
      const mi = parseInt(m[2], 10);
      if (h >= 0 && h <= 23 && mi >= 0 && mi <= 59) return h * 60 + mi;
    }
    const n = parseInt(String(str), 10);
    if (!isNaN(n) && n >= 0 && n <= 23) return n * 60;
    return fallback;
  }

  const startMin = parseTime(env.WORK_START, 9 * 60);
  const endMin = parseTime(env.WORK_END, 18 * 60);
  let lunchMin = null;
  if (env.LUNCH_START && env.LUNCH_END) {
    const ls = parseTime(env.LUNCH_START, -1);
    const le = parseTime(env.LUNCH_END, -1);
    if (ls >= 0 && le > ls) lunchMin = { s: ls, e: le };
  }
  let wage = parseFloat(String(env.HOURLY_WAGE == null ? '100' : env.HOURLY_WAGE).replace(/[^0-9.]/g, ''));
  if (isNaN(wage) || wage < 0) wage = 100;
  const wageText = Number.isInteger(wage) ? String(wage) : String(wage);

  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(startMin / 60), startMin % 60, 0);
  let end = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(endMin / 60), endMin % 60, 0);
  if (end.getTime() <= start.getTime()) end = new Date(end.getTime() + 24 * 3600 * 1000);

  let lunchStart = null;
  let lunchEnd = null;
  if (lunchMin) {
    lunchStart = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(lunchMin.s / 60), lunchMin.s % 60, 0);
    lunchEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate(), Math.floor(lunchMin.e / 60), lunchMin.e % 60, 0);
    if (lunchStart.getTime() < start.getTime()) {
      lunchStart = new Date(lunchStart.getTime() + 24 * 3600 * 1000);
      lunchEnd = new Date(lunchEnd.getTime() + 24 * 3600 * 1000);
    }
  }
  const startMs = start.getTime();
  const endMs = end.getTime();
  const workedToMs = Math.min(Math.max(now.getTime(), startMs), endMs);
  let elapsedSec = (workedToMs - startMs) / 1000;
  if (lunchStart) {
    const oS = Math.max(startMs, lunchStart.getTime());
    const oE = Math.min(workedToMs, lunchEnd.getTime());
    if (oE > oS) elapsedSec -= (oE - oS) / 1000;
  }
  const inLunch = lunchStart ? now.getTime() >= lunchStart.getTime() && now.getTime() < lunchEnd.getTime() : false;
  const restSet = new Set(String(env.REST_DAYS || '').split(/[,，、\s]+/).map((s) => parseInt(s, 10)).filter((n) => n >= 1 && n <= 31));
  const customMap = {};
  String(env.CUSTOM_DAYS || '').split(/[;；\n]+/).forEach((part) => {
    const mm = part.trim().match(/^(\d{1,2})\s*[:：]\s*([0-9]+(?:\.[0-9]+)?)\s*[:：]\s*([0-9]+(?:\.[0-9]+)?)$/);
    if (mm) {
      const dd = parseInt(mm[1], 10);
      if (dd >= 1 && dd <= 31) customMap[dd] = { h: parseFloat(mm[2]), amt: Math.floor(parseFloat(mm[3])) };
    }
  });
  const todayCustom = customMap[now.getDate()] || null;
  const isRest = restSet.has(now.getDate()) && !todayCustom;
  const earned = todayCustom ? todayCustom.amt : isRest ? 0 : elapsedSec / 3600 * wage;
  const yuan = Math.floor(earned);
  const pad2 = (n) => String(n).padStart(2, '0');
  const moneyText = `¥${yuan}元`;

  function fmtCd(targetMs) {
    const s = Math.max(0, Math.floor((targetMs - now.getTime()) / 1000));
    return `${pad2(Math.floor(s / 3600))}:${pad2(Math.floor(s % 3600 / 60))}`;
  }
  const cdText = fmtCd(end.getTime());
  const cdStartText = fmtCd(start.getTime());
  const cdLunchText = lunchEnd ? fmtCd(lunchEnd.getTime()) : '';
  const beforeStart = now.getTime() < start.getTime();
  const status = isRest ? '今日休息' : now.getTime() < start.getTime() ? '未上班' : now.getTime() > end.getTime() ? '已下班' : inLunch ? '午休中' : '赚钱中';
  const afterEnd = now.getTime() > end.getTime();
  const cdDisplay = afterEnd ? '已下班' : inLunch ? cdLunchText : beforeStart ? cdStartText : cdText;
  const cdChars = isRest ? ['今', '日', '休', '息'] : inLunch || (beforeStart && !afterEnd) ? ['距', '离', '上', '班'] : ['距', '离', '下', '班'];
  const lunchRange = lunchMin ? `${pad2(Math.floor(lunchMin.s / 60))}:${pad2(lunchMin.s % 60)}–${pad2(Math.floor(lunchMin.e / 60))}:${pad2(lunchMin.e % 60)}` : '';
  const timeRange = `${pad2(Math.floor(startMin / 60))}:${pad2(startMin % 60)}–${pad2(Math.floor(endMin / 60))}:${pad2(endMin % 60)}`;
  let spanMin = endMin - startMin;
  if (spanMin <= 0) spanMin += 1440;
  const dayHours = (spanMin - (lunchMin ? lunchMin.e - lunchMin.s : 0)) / 60;
  const dayAmount = Math.floor(dayHours * wage);
  function fmtH(h) { return (Number.isInteger(h) ? String(h) : String(Math.round(h * 10) / 10)) + 'H'; }

  const refreshAfter = new Date(now.getTime() + 60000).toISOString();

  const INK = { light: '#111111', dark: '#F2F2F7' };
  const SUB = { light: '#8A8A8E', dark: '#98989F' };

  function circleChar(ch, size) {
    return {
      type: 'stack',
      direction: 'column',
      alignItems: 'center',
      width: size,
      height: size,
      borderRadius: size / 2,
      borderWidth: 1.5,
      borderColor: INK,
      children: [
        { type: 'spacer' },
        { type: 'text', text: ch, font: { size: Math.round(size * 0.52), weight: 'bold' }, textColor: INK },
        { type: 'spacer' },
      ],
    };
  }

  function amountRow(big, small) {
    return {
      type: 'stack',
      direction: 'row',
      alignItems: 'end',
      children: [
        { type: 'text', text: '¥', font: { size: big, weight: 'bold' }, textColor: INK },
        { type: 'spacer', length: 2 },
        { type: 'text', text: String(yuan), font: { size: big, weight: 'bold' }, textColor: INK },
        { type: 'spacer', length: 3 },
        { type: 'text', text: '元', font: { size: small, weight: 'bold' }, textColor: INK },
      ],
    };
  }

  function countdownRow(circle, timeSize) {
    const kids = cdChars.map((ch) => circleChar(ch, circle));
    if (!isRest) {
      kids.push({ type: 'spacer', length: 8 });
      kids.push({ type: 'text', text: cdDisplay, font: { size: timeSize, weight: 'bold' }, textColor: INK });
    }
    return {
      type: 'stack',
      direction: 'row',
      alignItems: 'center',
      children: kids,
    };
  }

  function charSticker(w, h) {
    return {
      type: 'stack',
      direction: 'row',
      backgroundColor: '#FFFFFF',
      borderRadius: 14,
      padding: [4, 4, 4, 4],
      children: [
        { type: 'image', src: CHAR_IMG, width: w, height: h },
      ],
    };
  }

  if (family === 'accessoryCircular') {
    return {
      type: 'widget',
      padding: 0,
      children: [
        {
          type: 'stack', direction: 'column', alignItems: 'center',
          children: [
            { type: 'text', text: `¥${yuan}`, font: { size: 13, weight: 'bold' } },
            { type: 'text', text: '今日入账', font: { size: 8 } },
          ],
        },
      ],
      refreshAfter,
    };
  }
  if (family === 'accessoryInline') {
    return {
      type: 'widget',
      padding: 0,
      children: [
        { type: 'text', text: isRest ? `今日入账 ${moneyText} · 今日休息` : afterEnd ? `今日入账 ${moneyText} · 已下班` : inLunch ? `今日入账 ${moneyText} · 距上班 ${cdLunchText}` : beforeStart ? `今日入账 ${moneyText} · 距上班 ${cdStartText}` : `今日入账 ${moneyText} · 距下班 ${cdText}`, font: { size: 12 } },
      ],
      refreshAfter,
    };
  }
  if (family && family.indexOf('accessory') === 0) {
    return {
      type: 'widget',
      padding: [4, 8, 4, 8],
      children: [
        {
          type: 'stack', direction: 'column',
          children: [
            {
              type: 'stack', direction: 'row', alignItems: 'center',
              children: [
                { type: 'text', text: '今日入账', font: { size: 12, weight: 'bold' } },
                { type: 'spacer' },
                { type: 'text', text: moneyText, font: { size: 12, weight: 'bold' } },
              ],
            },
            { type: 'text', text: isRest ? '今日休息' : afterEnd ? '已下班' : inLunch ? `距上班 ${cdLunchText} · 午休中` : beforeStart ? `距上班 ${cdStartText} · ${status}` : `距下班 ${cdText} · ${status}`, font: { size: 11 } },
          ],
        },
      ],
      refreshAfter,
    };
  }

  if (family === 'systemSmall') {
    return {
      type: 'widget',
      padding: [12, 14, 12, 14],
      children: [
        {
          type: 'stack', direction: 'column',
          children: [
            { type: 'text', text: '今日入账', font: { size: 15, weight: 'bold' }, textColor: INK },
            { type: 'spacer', length: 8 },
            amountRow(28, 12),
            { type: 'spacer' },
            countdownRow(20, 15),
            { type: 'spacer', length: 6 },
            { type: 'text', text: `${status} · 时薪 ¥${wageText}`, font: { size: 10 }, textColor: SUB },
          ],
        },
      ],
      refreshAfter,
    };
  }

  if (family === 'systemLarge') {
    const Y = now.getFullYear();
    const MO = now.getMonth();
    const daysInMonth = new Date(Y, MO + 1, 0).getDate();
    const firstWday = new Date(Y, MO, 1).getDay();
    const todayD = now.getDate();
    const rows = Math.ceil((firstWday + daysInMonth) / 7);
    const CAL_BLUE = { light: '#2F7CF6', dark: '#5EA1FF' };
    const CELL_BG = { light: '#EAF3FE', dark: '#1F2A38' };
    const CELL_BD = { light: '#A9CCF7', dark: '#33506E' };
    const REST_BG = { light: '#E4F7EA', dark: '#1D3325' };
    const REST_BD = { light: '#8FD3A6', dark: '#2F5D3E' };
    const REST_TX = { light: '#1F9D55', dark: '#4CD964' };
    const AMT_TX = { light: '#F08C1A', dark: '#FFB340' };
    function dayCell(d) {
      if (d < 1 || d > daysInMonth) return { type: 'stack', flex: 1, children: [{ type: 'spacer' }] };
      const cust = customMap[d];
      const rest = restSet.has(d) && !cust;
      const isToday = d === todayD;
      const kids = [{ type: 'spacer' }];
      kids.push({ type: 'text', text: String(d), font: { size: 15, weight: 'bold' }, textColor: rest ? REST_TX : CAL_BLUE });
      if (rest) {
        kids.push({ type: 'text', text: '休', font: { size: 13, weight: 'bold' }, textColor: REST_TX });
      } else if (cust) {
        kids.push({ type: 'text', text: fmtH(cust.h), font: { size: 10, weight: 'bold' }, textColor: INK });
        kids.push({ type: 'text', text: `${cust.amt}元`, font: { size: 10, weight: 'bold' }, textColor: AMT_TX });
      } else if (d < todayD) {
        kids.push({ type: 'text', text: fmtH(dayHours), font: { size: 10, weight: 'bold' }, textColor: INK });
        kids.push({ type: 'text', text: `${dayAmount}元`, font: { size: 10, weight: 'bold' }, textColor: AMT_TX });
      } else if (isToday) {
        kids.push({ type: 'text', text: fmtH(elapsedSec / 3600), font: { size: 10, weight: 'bold' }, textColor: INK });
        kids.push({ type: 'text', text: `${yuan}元`, font: { size: 10, weight: 'bold' }, textColor: AMT_TX });
      }
      kids.push({ type: 'spacer' });
      return {
        type: 'stack', direction: 'column', alignItems: 'center', flex: 1,
        backgroundColor: rest ? REST_BG : CELL_BG,
        borderColor: isToday ? CAL_BLUE : rest ? REST_BD : CELL_BD,
        borderWidth: isToday ? 2.5 : 1,
        borderRadius: 7,
        children: kids,
      };
    }
    const weekNames = ['日', '一', '二', '三', '四', '五', '六'];
    const calKids = [
      {
        type: 'stack', direction: 'row', alignItems: 'center',
        children: [
          { type: 'text', text: '今日入账', font: { size: 16, weight: 'bold' }, textColor: INK },
          { type: 'spacer' },
          { type: 'text', text: `${Y}年${MO + 1}月`, font: { size: 14, weight: 'bold' }, textColor: INK },
        ],
      },
      { type: 'spacer', length: 8 },
      {
        type: 'stack', direction: 'row',
        children: weekNames.map((w) => ({
          type: 'stack', flex: 1, direction: 'column', alignItems: 'center',
          children: [{ type: 'text', text: w, font: { size: 11, weight: 'bold' }, textColor: SUB }],
        })),
      },
      { type: 'spacer', length: 6 },
    ];
    for (let r = 0; r < rows; r++) {
      if (r > 0) calKids.push({ type: 'spacer', length: 4 });
      const cells = [];
      for (let c = 0; c < 7; c++) {
        if (c > 0) cells.push({ type: 'spacer', length: 4 });
        cells.push(dayCell(r * 7 + c - firstWday + 1));
      }
      calKids.push({ type: 'stack', direction: 'row', flex: 1, children: cells });
    }
    return {
      type: 'widget',
      padding: [12, 14, 12, 14],
      children: [{ type: 'stack', direction: 'column', children: calKids }],
      refreshAfter,
    };
  }

  return {
    type: 'widget',
    padding: [12, 16, 12, 16],
    children: [
      {
        type: 'stack', direction: 'row', alignItems: 'center',
        children: [
          {
            type: 'stack', direction: 'column', flex: 1,
            children: [
              { type: 'text', text: '今日入账', font: { size: 17, weight: 'bold' }, textColor: INK },
              { type: 'spacer' },
              amountRow(44, 15),
              { type: 'spacer', length: 10 },
              countdownRow(25, 20),
            ],
          },
          { type: 'spacer', length: 6 },
          charSticker(112, 136),
        ],
      },
    ],
    refreshAfter,
  };
}
